const notes={frutas:'Frutas & baunilha: uma combinação leve para celebrar em boa companhia.',chocolate:'Chocolate de verdade: recheio cremoso e sabor intenso para quem ama cacau.',docinhos:'Pequenas felicidades: escolha uma caixa para presentear ou docinhos para a sua mesa.'};document.querySelectorAll('[data-flavor]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-flavor]').forEach(item=>{item.classList.toggle('selected',item===button);item.setAttribute('aria-pressed',String(item===button));});document.querySelector('.flavor-note').textContent=notes[button.dataset.flavor];}));